#Answer Relevancy Metric 
# Answer Relevancy checks whether the agent's answer actually addresses the user's question.
# It uses an LLM as a judge to evaluate the relationship between:
# •	input — the question asked by the user.
# •	actual_output — the answer generated by your RAG agent.
# It does not directly check whether the answer is factually correct

from deepeval.test_case import LLMTestCase
from deepeval.metrics import AnswerRelevancyMetric
from app.rag_agent import rag_support_agent_with_context
from app.retriever import build_vector_store
import pytest

@pytest.fixture(scope="session", autouse=True)
def initialize_vector_store():
    build_vector_store()

@pytest.fixture
def answer_relevency_metric():
    return AnswerRelevancyMetric(
            threshold=0.7,
            model="gpt-4.1-mini",
            include_reason= True
        )

@pytest.mark.parametrize(
    "input, actual_output, expected_pass",
    [
        (
            "How much does the Premium plan cost?",
            "The Premium plan costs $25 per month.",
            True
        ),
        (
            "How much does the Premium plan cost?",
            "You can cancel your subscription at any time.",
            False
           
        ),
        (
            "How much does the Premium plan cost, and what features does it include?",
            "The Premium plan costs $25 per month.",
            True
        ),
    ],
)

def test_answer_relevancy_metric_eval(input, actual_output,expected_pass, answer_relevency_metric):
    test_case = LLMTestCase(
        input = input,
        actual_output= actual_output
    )

    answer_relevency_metric.measure(test_case)

    print(f"Metric Scrore: {answer_relevency_metric.score}\n"
          f"Metric Resaon: {answer_relevency_metric.reason}")

    assert answer_relevency_metric.is_successful() == expected_pass, (
        f"Expected pass: {expected_pass}\n"
        f"Actual score: {answer_relevency_metric.score}\n"
        f"Reason: {answer_relevency_metric.reason}"
    )

# Test answer relevency metric from the agent response
@pytest.mark.parametrize("question", [
    ("How much does the Premium plan cost?"),
    ("How do monthly subscriptions renew?"),
    ("How does upgrading from Basic to Premium work?"),
    ("What happens after I cancel my subscription?"),
    ("Am I guaranteed a refund if I request one?")
])
def test_answer_relevancy_metric_agent(question, answer_relevency_metric):

    response = rag_support_agent_with_context(question)
    test_case = LLMTestCase(
        input = question,
        actual_output= response["answer"]
    )

    answer_relevency_metric.measure(test_case)

    print(f"\nQuestion: {question}")
    print(f"Answer: {response['answer']}")
    print(f"Score: {answer_relevency_metric.score}")
    print(f"Reason: {answer_relevency_metric.reason}")

    assert answer_relevency_metric.is_successful(), (
        f"Question: {question}\n"
        f"Score: {answer_relevency_metric.score}\n"
        f"Reason: {answer_relevency_metric.reason}"
    )

    

